    end end.
    - rewrite !edenot_add_lit. unfold adenot, v_addi. cbn [a_base a_off edenot ev ENVb ENV]. rewrite P0, !u_small by lia. lia.
    - rewrite !edenot_add_lit. unfold adenot, v_addi. cbn [a_base a_off edenot ev ENVb ENV]. rewrite P0, !u_small by lia. lia.
