      change (Env (vals_ev (vals ++ junk_vals R')) (blobs_ev (blobs0 a0s path hw rdraw ++ [fdata]))) with (ENVb (vals ++ junk_vals R')) in HR, HK.
      run_blockQ scr0 103%nat.
